import JavaScriptKit

// Typed bindings for the browser APIs the remote control uses, generated by BridgeJS (the
// `BridgeJS` build plugin on this target). Every member is `throws(JSException)`: a JS exception
// (blocked storage, a closed socket) becomes a Swift error instead of trapping the Wasm.
// `BrowserServices.swift` wraps these into the small API the rest of the app uses; nothing outside
// this module calls them directly.

// MARK: Page

@JSClass struct Location {
  @JSGetter var hash: String
  @JSGetter var href: String
  @JSGetter var origin: String
  @JSGetter var pathname: String
  @JSGetter var search: String
  @JSGetter(jsName: "protocol") var scheme: String
}

@JSClass struct History {
  @JSGetter var state: JSValue
  @JSFunction func replaceState(_ state: JSValue, _ unused: String, _ url: String) throws(JSException)
}

@JSClass struct Navigator {
  @JSGetter var onLine: Bool
}

@JSClass struct Document {
  @JSGetter var visibilityState: String
  @JSFunction func addEventListener(_ type: String, _ listener: JSTypedClosure<() -> Void>) throws(JSException)
  @JSFunction func removeEventListener(_ type: String, _ listener: JSTypedClosure<() -> Void>) throws(JSException)
  @JSFunction(jsName: "addEventListener")
  func addKeyListener(_ type: String, _ listener: JSTypedClosure<(KeyboardEvent) -> Void>) throws(JSException)
  @JSFunction(jsName: "removeEventListener")
  func removeKeyListener(_ type: String, _ listener: JSTypedClosure<(KeyboardEvent) -> Void>) throws(JSException)
  @JSFunction(jsName: "addEventListener")
  func addCancelableListener(
    _ type: String, _ listener: JSTypedClosure<(DOMEvent) -> Void>, _ options: ListenerOptions
  ) throws(JSException)
}

@JSClass struct KeyboardEvent {
  @JSGetter var key: String
  @JSGetter(jsName: "repeat") var isRepeat: Bool
  @JSGetter var ctrlKey: Bool
  @JSGetter var metaKey: Bool
  @JSGetter var altKey: Bool
  @JSFunction func preventDefault() throws(JSException)
}

@JSClass struct DOMEvent {
  @JSFunction func preventDefault() throws(JSException)
}

@JS struct ListenerOptions {
  var passive: Bool
}

@JSClass struct Storage {
  @JSFunction func getItem(_ key: String) throws(JSException) -> String?
  @JSFunction func setItem(_ key: String, _ value: String) throws(JSException)
  @JSFunction func removeItem(_ key: String) throws(JSException)
}

@JSClass struct PerformanceEntry {
  @JSGetter var type: String
}

@JSClass struct Performance {
  @JSFunction func now() throws(JSException) -> Double
  @JSFunction func getEntriesByType(_ type: String) throws(JSException) -> [PerformanceEntry]
}

@JSClass(from: .global) struct URLSearchParams {
  @JSFunction init(_ query: String) throws(JSException)
  @JSFunction func get(_ name: String) throws(JSException) -> String?
}

@JSClass(from: .global) struct URL {
  @JSFunction init(_ url: String, _ base: String) throws(JSException)
  @JSGetter var href: String
  @JSSetter func setHash(_ value: String) throws(JSException)
  @JSSetter(jsName: "protocol") func setScheme(_ value: String) throws(JSException)
}

@JSGetter(from: .global) var location: Location
@JSGetter(from: .global) var history: History
@JSGetter(from: .global) var navigator: Navigator
@JSGetter(from: .global) var document: Document
@JSGetter(from: .global) var performance: Performance
/// Reading `sessionStorage` / `localStorage` itself throws when storage is blocked.
@JSGetter(from: .global) var sessionStorage: Storage
@JSGetter(from: .global) var localStorage: Storage
@JSGetter(from: .global) var opener: JSObject?

@JSFunction(from: .global) func scrollTo(_ x: Double, _ y: Double) throws(JSException)

/// Window events (`online`, `offline`, `hashchange`, `resize`).
@JSFunction(from: .global)
func addEventListener(_ type: String, _ listener: JSTypedClosure<() -> Void>) throws(JSException)
@JSFunction(from: .global)
func removeEventListener(_ type: String, _ listener: JSTypedClosure<() -> Void>) throws(JSException)

// MARK: JSON and crypto

@JSClass struct JSONNamespace {
  /// Throws on malformed text.
  @JSFunction func parse(_ text: String) throws(JSException) -> JSValue
  @JSFunction func stringify(_ value: JSValue) throws(JSException) -> String
}

@JSGetter(jsName: "JSON", from: .global) var json: JSONNamespace

@JSClass struct Crypto {
  @JSFunction func getRandomValues(_ array: JSTypedArray<UInt8>) throws(JSException) -> JSTypedArray<UInt8>
}

@JSGetter(from: .global) var crypto: Crypto

// MARK: WebSocket

@JSClass struct MessageEvent {
  @JSGetter var data: JSValue
}

@JSClass struct CloseEvent {
  @JSGetter var code: Int
  @JSGetter var reason: String
}

@JSClass(from: .global) struct WebSocket {
  @JSFunction init(_ url: String) throws(JSException)
  @JSGetter var readyState: Int
  @JSFunction func send(_ data: String) throws(JSException)
  @JSFunction func close() throws(JSException)
  @JSSetter(jsName: "onopen") func setOnOpen(_ handler: JSTypedClosure<() -> Void>?) throws(JSException)
  @JSSetter(jsName: "onmessage")
  func setOnMessage(_ handler: JSTypedClosure<(MessageEvent) -> Void>?) throws(JSException)
  @JSSetter(jsName: "onclose") func setOnClose(_ handler: JSTypedClosure<(CloseEvent) -> Void>?) throws(JSException)
}

// MARK: fetch

@JSClass struct AbortSignal {}

@JSClass(from: .global) struct AbortController {
  @JSFunction init() throws(JSException)
  @JSGetter var signal: AbortSignal
  @JSFunction func abort() throws(JSException)
}

@JSClass struct Response {
  @JSGetter var ok: Bool
  @JSGetter var status: Int
  /// A `Promise<string>`.
  @JSFunction func text() throws(JSException) -> JSObject
}

@JS struct FetchOptions {
  var method: String
  var headers: [String: String]
  var body: String
  var signal: AbortSignal?
}

/// Returns a `Promise<Response>`.
@JSFunction(from: .global) func fetch(_ url: String, _ options: FetchOptions) throws(JSException) -> JSObject

// MARK: Provided by web/main.js

/// A QR code image (data URL), from the bundled QR library injected through `getImports()`.
@JSFunction func qrCodeDataURL(_ text: String) throws(JSException) -> String
